        MOD = 10**9 + 7
        n = len(nums)
        dp = [0] * n
        dp[0] = max(0, nums[0])
        for i in range(1, n):
            dp[i] = max(dp[i-1], dp[i-2] + nums[i], nums[i])
        result = 0
        for pos, x in queries:
            nums[pos] = x
            dp[pos] = max(dp[pos-1], dp[pos-2] + nums[pos], nums[pos])
            for i in range(pos+1, n):
                dp[i] = max(dp[i-1], dp[i-2] + nums[i], nums[i])
            result = (result + dp[-1]) % MOD
        return result

class Solution:
    def minimumSubstringsInPartition(self, s: str) -> int:
        def is_balanced(sub):
            if not sub:
                return False
            char_count = {}
            for char in sub:
                if char in char_count:
                    char_count[char] += 1
                else:
                    char_count[char] = 1
            return len(set(char_count.values())) == 1

        def min_substrings(s, start, memo):
            if start == len(s):
                return 0
            if start in memo:
                return memo[start]
            min_count = float('inf')
            for end in range(start + 1, len(s) + 1):
                if is_balanced(s[start:end]):
                    min_count = min(min_count, 1 + min_substrings(s, end, memo))
            memo[start] = min_count
            return min_count

        return min_substrings(s, 0, {})

